<?php
declare(strict_types=1);
require dirname(__DIR__).'/nexus/core/bootstrap.php';
header('Content-Type: text/html; charset=utf-8');
header('Cache-Control: no-store, no-cache, must-revalidate');
function ch_escape($v): string {return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$worlds=[];$assignments=[];$failed=false;
try {
 $db=nexus_db(nexus_config(),'core');
 $worlds=nexus_rows($db,"SELECT `IMC GW` gw,`IMC_WORLD_ID` code,`IMC GW Name` name,`Active Club` active_clubs FROM `IMC Game World Codex Global` WHERE `IMC_WORLD_ID` IN ('IMC-001','IMC-002','IMC-003','IMC-004','IMC-005','IMC-006','IMC-007') ORDER BY `IMC_WORLD_ID`");
 if(count($worlds)!==7) throw new RuntimeException('worlds_incomplete');
 $assignments=nexus_rows($db,"SELECT a.id,a.team_id,a.game_world_id,a.manager_id,m.full_name,a.assignment_type,a.start_date,a.end_date,COALESCE(NULLIF(c.nexus_view,''),c.name,n.name,a.team_name) team_name,COALESCE(c.image_url,n.image_url) image_url FROM `IMC Manager Assignment Global` a JOIN `IMC Manager Codex Global` m ON m.manager_id=a.manager_id JOIN `IMC Game World Codex Global` w ON w.`IMC GW`=a.game_world_id LEFT JOIN `IMC Game World Club Mapping` cm ON a.assignment_type='club' AND cm.`Game World`=a.game_world_id AND cm.`SM World Club ID`=a.team_id LEFT JOIN `IMC Club Codex Global` c ON c.id=cm.`Club ID` LEFT JOIN `IMC Game World National Team Mapping` nm ON a.assignment_type='national_team' AND nm.`Game World`=a.game_world_id AND nm.`SM World National Club ID`=a.national_team_id LEFT JOIN `IMC National Team Codex Global` n ON n.id=nm.`National Team ID` WHERE w.`IMC_WORLD_ID` IN ('IMC-001','IMC-002','IMC-003','IMC-004','IMC-005','IMC-006','IMC-007') ORDER BY m.full_name,w.`IMC_WORLD_ID`,a.assignment_type,a.start_date");
} catch(Throwable $e) {$failed=true;http_response_code(503);error_log('Clubhouse: '.$e->getMessage());}
$today=(new DateTimeImmutable('now',new DateTimeZone('Europe/Rome')))->format('Y-m-d');
$coached=[];
foreach($assignments as $a) {
 if($a['assignment_type']==='club' && $a['team_id']!==null && (!$a['start_date'] || $a['start_date']<=$today) && (!$a['end_date'] || $a['end_date']>=$today)) {
  $coached[$a['game_world_id']][(string)$a['team_id']]=true;
 }
}
?>
<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Clubhouse | Italian Masters Club</title><meta name="theme-color" content="#f7f4ed"><link rel="canonical" href="https://www.italianmastersclub.it/clubhouse/"><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet"><style>
*{box-sizing:border-box}body{margin:0;background:#ffffff;color:#142b45;font-family:Inter,sans-serif}a{color:inherit;text-decoration:none}header,main,footer{max-width:1180px;margin:auto;padding:24px}header{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #d9dfe5}.brand{display:flex;align-items:center;gap:12px;font-weight:800;font-size:13px;letter-spacing:.08em}.brand img{width:44px;height:44px;object-fit:contain}.eyebrow{color:#142b45;letter-spacing:.16em;font-size:11px;font-weight:700;text-transform:uppercase}h1{font-size:clamp(46px,9vw,88px);letter-spacing:-.07em;margin:16px 0}p{color:#52647a;line-height:1.6}.hero{padding:35px 0 30px}.worlds{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:24px 0 48px}.world{padding:20px;border:1px solid #d9dfe5;border-radius:16px;background:linear-gradient(135deg,#ffffff,#ffffff);min-height:118px;display:flex;flex-direction:column;justify-content:space-between;gap:14px}.world:hover{border-color:#d9dfe5}.world strong{font-size:16px}.world small{color:#142b45;font-size:11px}.world-counts{display:flex;gap:16px;flex-wrap:wrap;border-top:1px solid #d9dfe5;padding-top:12px}.world-counts span{font-size:11px;color:#52647a}.world-counts b{display:block;font-size:20px;color:#142b45;margin-bottom:4px}.controls{display:flex;gap:12px;flex-wrap:wrap}input,select,button{font:inherit;font-size:14px;color:inherit;border:1px solid #d9dfe5;border-radius:10px;padding:13px;background:#ffffff;min-height:46px}input{flex:1;min-width:180px}button{cursor:pointer}button[aria-pressed=true]{background:#e3d3ac;color:#142b45;border-color:#d9dfe5}.tabs{display:flex;gap:8px;margin:20px 0}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.card{border:1px solid #d9dfe5;border-radius:18px;padding:22px;background:#ffffff}.card h3{margin:8px 0 22px;font-size:22px;letter-spacing:-.04em}.card>small{color:#52647a}.group{border-top:1px solid #d9dfe5;padding-top:16px;margin-top:18px}.group h4{font-size:12px;color:#142b45;margin:0 0 12px}.team{display:flex;gap:12px;margin:15px 0;align-items:center}.team img{height:34px;width:34px;object-fit:contain}.team div{min-width:0}.team strong{font-size:14px}.team small{display:block;color:#52647a;font-size:11px;margin-top:6px}.status{font-size:10px!important;color:#208455!important}.ended{color:#a30000!important}footer{margin-top:48px;border-top:1px solid #d9dfe5;font-size:12px;color:#52647a}#summary{font-size:13px}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid #d9dfe5;outline-offset:4px}@media(max-width:800px){.worlds{grid-template-columns:repeat(2,1fr)}.cards{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:520px){header,main,footer{padding:20px}.brand{font-size:11px}.cards{grid-template-columns:1fr}.hero{padding-top:24px}.world{padding:16px}.controls>*{width:100%}.worlds{margin-bottom:34px}header>a{font-size:13px}}
</style><link rel="stylesheet" href="/site-assets/css/imc-ivory.css?v=20261104ivory1"></head><body><header><a class="brand" href="/"><img src="/site-assets/images/imc-logo.png" alt="IMC"><span>ITALIAN<br>MASTERS CLUB</span></a><a href="/">Home IMC ↗</a></header><main><section class="hero"><span class="eyebrow">Sette mondi. Un solo Club.</span><h1>Clubhouse.</h1><p>I nostri mondi, i manager e le loro panchine.</p></section>
<?php if($failed): ?><p role="alert">Le assegnazioni sono temporaneamente non disponibili.</p><a href="/clubhouse/">Riprova →</a><?php else: ?>
<nav class="worlds" aria-label="Mondi IMC"><?php foreach($worlds as $w): $url=$w['gw']==='GW001'?'/roadtohistory/':'/nexus/?world='.rawurlencode($w['gw']); ?><a class="world" href="<?=ch_escape($url)?>"><small><?=ch_escape($w['code'])?> ↗</small><strong><?=ch_escape($w['name'])?></strong><span class="world-counts"><span><b><?=ch_escape($w['active_clubs'])?></b>Active</span><span><b><?=count($coached[$w['gw']]??[])?></b>Allenate</span></span></a><?php endforeach ?></nav>
<section aria-labelledby="managers-title"><span class="eyebrow">Le persone del Club</span><h2 id="managers-title">Manager e assegnazioni</h2><div class="tabs" aria-label="Stato incarichi"><button data-mode="active" aria-pressed="true">Attivi</button><button data-mode="ended" aria-pressed="false">Storico</button></div><div class="controls"><input id="search" type="search" aria-label="Cerca manager o squadra" placeholder="Cerca manager o squadra…"><select id="world" aria-label="Filtra per mondo"><option value="">Tutti i mondi</option><?php foreach($worlds as $w): ?><option value="<?=ch_escape($w['gw'])?>"><?=ch_escape($w['code'].' · '.$w['name'])?></option><?php endforeach ?></select></div><p id="summary" role="status" aria-live="polite"></p><div id="cards" class="cards"></div><noscript>Attiva JavaScript per consultare le assegnazioni.</noscript></section>
<script>
const worlds=<?=json_encode($worlds,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,rows=<?=json_encode($assignments,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,today=<?=json_encode($today)?>;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=v=>v?v.slice(0,10).split('-').reverse().join('/'):'—';let mode='active';
const search=document.getElementById('search'),filter=document.getElementById('world'),cards=document.getElementById('cards');
function render(){const managers=new Map();let count=0;const q=search.value.trim().toLocaleLowerCase('it');
for(const a of rows){const active=(!a.start_date||a.start_date<=today)&&(!a.end_date||a.end_date>=today);const ended=a.end_date&&a.end_date<today;if(!(mode==='active'?active:ended)||filter.value&&a.game_world_id!==filter.value)continue;const id=a.manager_id;if(!managers.has(id))managers.set(id,{name:a.full_name,id,items:[]});managers.get(id).items.push(a)}
const visible=[...managers.values()].filter(m=>[m.name,...m.items.map(a=>a.team_name)].join(' ').toLocaleLowerCase('it').includes(q));
cards.innerHTML=visible.map(m=>'<article class="card"><small>'+esc(m.id)+'</small><h3>'+esc(m.name)+'</h3>'+worlds.map(w=>{const aa=m.items.filter(a=>a.game_world_id===w.gw);count+=aa.length;if(!aa.length)return '';return '<div class="group"><h4>'+esc(w.code+' · '+w.name)+'</h4>'+aa.map(a=>{const src=String(a.image_url||'').replace(/^http:/,'https:');return '<div class="team">'+(/^https:\/\//.test(src)?'<img loading="lazy" src="'+esc(src)+'" alt="">':'')+'<div><strong>'+esc(a.team_name||'Squadra non disponibile')+'</strong><small>'+(a.assignment_type==='national_team'?'Nazionale':'Club')+' · '+date(a.start_date)+(a.end_date?' – '+date(a.end_date):'')+'</small><small class="status '+(mode==='ended'?'ended':'')+'">'+(mode==='ended'?'Ended':'Active')+'</small></div></div>'}).join('')+'</div>'}).join('')+'</article>').join('')||'<p>Nessuna assegnazione trovata.</p>';
document.getElementById('summary').textContent=visible.length+' manager · '+count+' incarichi';cards.querySelectorAll('img').forEach(i=>i.onerror=()=>i.hidden=true)}
search.oninput=render;filter.onchange=render;document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(t=>t.setAttribute('aria-pressed',String(t===b)));render()});render();
</script><?php endif ?></main><footer>ITALIAN MASTERS CLUB · CLUBHOUSE</footer></body></html>
